package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8StreamJsonParser._parseNumber
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class UTF8StreamJsonParser__parseNumber_TriageGen2Test {

    private TestableUTF8StreamJsonParser parser;

    // Constants matching Jackson internal logic for testing
    private static final int INT_MINUS = '-';
    private static final int INT_0 = '0';
    private static final int INT_9 = '9';

    /**
     * Subclass to expose protected method _parseNumber
     */
    private static class TestableUTF8StreamJsonParser extends UTF8StreamJsonParser {
        public TestableUTF8StreamJsonParser(IOContext ctxt, int features, InputStream in, ObjectCodec codec, 
                                           BytesToNameCanonicalizer sym, byte[] inputBuffer, int start, int end, 
                                           boolean bufferRecyclable) {
            super(ctxt, features, in, codec, sym, inputBuffer, start, end, bufferRecyclable);
        }

        @Override
        public JsonToken _parseNumber(int c) throws IOException, JsonParseException {
            return super._parseNumber(c);
        }
    }

    private void setupParser(String json) throws IOException {
        byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
        parser = new TestableUTF8StreamJsonParser(
                IOContext.bootstrap{},
                0,
                new ByteArrayInputStream(bytes),
                null,
                null,
                bytes,
                0,
                bytes.length,
                true
        );
    }

    @Test
    public void testParsePositiveInteger() throws IOException, JsonParseException {
        setupParser("123");
        // We need to simulate the parser state where it's about to parse a number.
        // Since _parseNumber is called internally by nextToken, we use a trick or assume 
        // the internal pointer is at the start of the number.
        // For this specific unit test, we manually trigger the method.
        // Note: In a real scenario, the pointer would be advanced by previous logic.
        // We simulate the first char '1' (49) being passed.

        // We have to manually adjust the parser's internal state via reflection if we wanted 
        // perfect accuracy, but here we assume the input matches the logic.
        // Since we can't easily set private fields like _inputPtr without reflection, 
        // we rely on the constructor's input buffer.

        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
    }

    @Test
    public void testParseNegativeInteger() throws IOException, JsonParseException {
        setupParser("-456");
        JsonToken token = parser._parseNumber('-');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("-456", parser.getValueAsString());
    }

    @Test
    public void testParseLeadingZeroInvalid() throws IOException, JsonParseException {
        setupParser("0123");
        // Jackson's _verifyNoLeadingZeroes usually throws JsonParseException for "01"
        try {
            parser._parseNumber('0');
            org.junit.Assert.fail("Should have thrown JsonParseException for leading zero");
        } catch (JsonParseException e) {
            // Expected
        }
    }

    @Test
    public void testParseSingleZero() throws IOException, JsonParseException {
        setupParser("0");
        JsonToken token = parser._parseNumber('0');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("0", parser.getValueAsString());
    }

    @Test
    public void testParseFloatWithDot() throws IOException, JsonParseException {
        setupParser("123.45");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("123.45", parser.getValueAsString());
    }

    @Test
    public void testParseScientificNotationE() throws IOException, JsonParseException {
        setupParser("1.2E10");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals("1.2E10", parser.getValueAsString());
    }

    @Test
    public void testParseScientificNotationSmallE() throws IOException, JsonParseException {
        setupParser("1e-5");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
    }

    @Test
    public void testParseNegativeInvalidStart() throws IOException, JsonParseException {
        setupParser("-a");
        try {
            parser._parseNumber('-');
            org.junit.Assert.fail("Should have thrown JsonParseException for '-' followed by non-digit");
        } catch (JsonParseException e) {
            // Expected
        }
    }

    @Test
    public void testParseNumberSplitAcrossBuffer() throws IOException, JsonParseException {
        // This tests the 'return _parserNumber2' branch by making the number longer than the segment
        // We use a large number to trigger segment switching logic if possible, 
        // but since we control the buffer size in the constructor, we can simulate it.
        byte[] smallBuffer = "12345678901234567890".getBytes();
        parser = new TestableUTF8StreamJsonParser(
                IOContext.bootstrap{},
                0,
                new ByteArrayInputStream(smallBuffer),
                null,
                null,
                smallBuffer,
                0,
                smallBuffer.length,
                true
        );

        // We pass '1' and let it loop.
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
    }

    @Test
    public void testParseWithTrailingChar() throws IOException, JsonParseException {
        setupParser("123,");
        JsonToken token = parser._parseNumber('1');
        assertEquals(JsonToken.VALUE_NUMBER_INT, token);
        assertEquals("123", parser.getValueAsString());
        // The comma should have been pushed back (handled by --_inputPtr)
    }
}
